import json
import re
from collections import Counter
# Constants
REPLACE_NONE = "None"
def task_func(json_str):
    data = json.loads(json_str)
    def remove_none(obj):
        if isinstance(obj, dict):
            return {k: remove_none(v) for k, v in obj.items() if v is not None}
        elif isinstance(obj, list):
            return [remove_none(item) for item in obj if item is not None]
        else:
            return obj
    processed_data = remove_none(data)
    email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
    def replace_emails(obj):
        if isinstance(obj, dict):
            return {k: replace_emails(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [replace_emails(item) for item in obj]
        elif isinstance(obj, str):
            return re.sub(email_pattern, REPLACE_NONE, obj)
        else:
            return obj
    processed_data = replace_emails(processed_data)
    def extract_values(obj):
        values = []
        if isinstance(obj, dict):
            for v in obj.values():
                values.extend(extract_values(v))
        elif isinstance(obj, list):
            for item in obj:
                values.extend(extract_values(item))
        else:
            values.append(obj)
        return values
    all_values = extract_values(processed_data)
    value_counts = Counter(all_values)
    return {"data": processed_data, "value_counts": value_counts}
